def append(self, entry):
    if not isinstance(entry.id, str) or not entry.id.strip():
        raise ValueError('nonempty entry identity required')
    if type(entry.cents) is not int or entry.cents <= 0:
        raise ValueError('positive integer cents required')
    if entry.kind not in {'purchase', 'refund', 'payment'}:
        raise ValueError('unknown entry type')
    with self.lock:
        old = self.entries.get(entry.id)
        if old:
            if old != entry:
                raise ValueError('entry identity conflict')
            return
        if entry.kind == 'refund':
            purchase = self.entries.get(entry.parent)
            if not purchase or purchase.kind != 'purchase':
                raise ValueError('missing purchase provenance')
            used = sum(e.cents for e in self.entries.values()
                       if e.kind == 'refund' and e.parent == entry.parent)
            if used + entry.cents > purchase.cents:
                raise ValueError('refund exceeds purchase')
        elif entry.parent:
            raise ValueError('unexpected parent')
        self.entries[entry.id] = entry

def snapshot(self):
    with self.lock:
        return tuple(self.entries.values())

def event(self, ident, generation, kind, scope):
    if not isinstance(ident, str) or not ident.strip():
        raise ValueError('nonempty event identity required')
    if type(generation) is not int or generation < 1:
        raise ValueError('positive integer generation required')
    required = {'delivered': 'carrier', 'dispute': 'customer',
                'activate': 'customer_verified'}
    if kind not in required or required[kind] != scope:
        raise PermissionError('scope mismatch')
    payload = json.dumps([generation, kind, scope])
    with self.db:
        self.db.execute('BEGIN IMMEDIATE')
        old = self.db.execute('SELECT payload FROM events WHERE id=?',
                              (ident,)).fetchone()
        if old:
            if old[0] != payload:
                raise ValueError('event conflict')
            return self.state()
        current, carrier, disputed, active = self.state()
        if generation > current:
            raise ValueError('future generation; event not consumed')
        if generation == current:
            if kind == 'delivered':
                carrier = 'delivered'
            elif kind == 'dispute':
                disputed, active = 1, 0
            elif kind == 'activate':
                if disputed:
                    raise ValueError('dispute requires separate resolution')
                active = 1
            self.db.execute('UPDATE card SET carrier=?,disputed=?,active=? '
                            'WHERE id=1', (carrier, disputed, active))
        self.db.execute('INSERT INTO events VALUES(?,?)', (ident, payload))
    return self.state()

def reserve(self, owner, ident, card, cents):
    if not isinstance(ident, str) or not ident.strip():
        raise ValueError('nonempty reservation identity required')
    if type(cents) is not int or cents <= 0:
        raise ValueError('integer cents required')
    with self.db:
        self.db.execute('BEGIN IMMEDIATE')
        available = self.preview(owner, card)
        old = self.db.execute('SELECT card,cents FROM holds WHERE id=?',
                              (ident,)).fetchone()
        if old:
            if old != (card, cents):
                raise ValueError('reservation conflict')
            return ident
        if cents > available:
            raise ValueError('insufficient global credit or card budget')
        self.db.execute('UPDATE account SET free=free-? WHERE owner=?',
                        (cents, owner))
        self.db.execute('UPDATE cards SET spent=spent+? WHERE id=?',
                        (cents, card))
        self.db.execute('INSERT INTO holds VALUES(?,?,?)', (ident, card, cents))
    return ident

def set_cap(self, owner, card, cap):
    if type(cap) is not int or cap < 0:
        raise ValueError('integer cap required')
    with self.db:
        if self.db.execute('UPDATE cards SET cap=? WHERE id=? AND owner=?',
                           (cap, card, owner)).rowcount != 1:
            raise PermissionError('not owned')

class CreditView {
  final int globalAvailableCents;
  final int virtualCapCents;
  final int virtualSpentCents;
  final DateTime asOf;
  CreditView(this.globalAvailableCents, this.virtualCapCents,
      this.virtualSpentCents, this.asOf);

  int get previewCents {
    final remaining = virtualCapCents - virtualSpentCents;
    final bounded = remaining < globalAvailableCents
        ? remaining : globalAvailableCents;
    return bounded < 0 ? 0 : bounded;
  }
